package android.widget;public class CheckBox extends Button {public interface OnCheckedChangeListener {void onCheckedChanged(CheckBox box,boolean checked);}private boolean checked;private OnCheckedChangeListener listener;public CheckBox(android.content.Context context){super(context);}public void setButtonTintList(android.content.res.ColorStateList value){}public void setChecked(boolean value){checked=value;if(listener!=null)listener.onCheckedChanged(this,value);}public boolean isChecked(){return checked;}public void setOnCheckedChangeListener(OnCheckedChangeListener value){listener=value;}}
